package com.yuu.translate;
import android.accessibilityservice.AccessibilityService; import android.view.accessibility.AccessibilityEvent; import android.graphics.*; import android.os.*; import android.view.*; import android.widget.*; import android.content.*; import java.util.*;
import com.google.mlkit.nl.translate.*; import com.google.mlkit.vision.common.InputImage; import com.google.mlkit.vision.text.*; import com.google.mlkit.vision.text.chinese.ChineseTextRecognizerOptions;
public class TranslateService extends AccessibilityService {
 WindowManager wm; LinearLayout controls; final List<View> labels=new ArrayList<>(); Translator translator; TextRecognizer recognizer; Handler handler=new Handler(Looper.getMainLooper()); boolean busy=false; int generation=0; Button en;
 public void onServiceConnected(){wm=(WindowManager)getSystemService(WINDOW_SERVICE); translator=Translation.getClient(new TranslatorOptions.Builder().setSourceLanguage(TranslateLanguage.CHINESE).setTargetLanguage(TranslateLanguage.ENGLISH).build()); recognizer=TextRecognition.getClient(new ChineseTextRecognizerOptions.Builder().build()); controls=new LinearLayout(this); en=new Button(this); en.setText("EN"); Button clear=new Button(this);clear.setText("×"); controls.addView(en);controls.addView(clear); WindowManager.LayoutParams p=params(-2,-2,false);p.gravity=Gravity.RIGHT|Gravity.CENTER_VERTICAL;wm.addView(controls,p);en.setOnClickListener(v->scan());clear.setOnClickListener(v->{generation++;clearLabels();}); }
 WindowManager.LayoutParams params(int w,int h,boolean passive){return new WindowManager.LayoutParams(w,h,WindowManager.LayoutParams.TYPE_ACCESSIBILITY_OVERLAY,WindowManager.LayoutParams.FLAG_NOT_FOCUSABLE|(passive?WindowManager.LayoutParams.FLAG_NOT_TOUCHABLE:0),PixelFormat.TRANSLUCENT);}
 void clearLabels(){for(View v:labels)wm.removeView(v);labels.clear();}
 void scan(){if(busy)return;busy=true;int token=++generation;clearLabels();controls.setVisibility(View.INVISIBLE);handler.postDelayed(()->takeScreenshot(Display.DEFAULT_DISPLAY,getMainExecutor(),new TakeScreenshotCallback(){public void onSuccess(ScreenshotResult s){controls.setVisibility(View.VISIBLE); android.hardware.HardwareBuffer buf=s.getHardwareBuffer(); Bitmap hw=Bitmap.wrapHardwareBuffer(buf,s.getColorSpace()); Bitmap bmp=hw==null?null:hw.copy(Bitmap.Config.ARGB_8888,false);if(hw!=null)hw.recycle();buf.close();if(bmp==null){busy=false;return;}recognizer.process(InputImage.fromBitmap(bmp,0)).addOnSuccessListener(result->{for(Text.TextBlock block:result.getTextBlocks()){String original=block.getText();Rect r=block.getBoundingBox();if(r==null||!original.matches("(?s).*\\p{IsHan}.*"))continue;translator.translate(original).addOnSuccessListener(english->{if(token==generation)show(r,english);}).addOnFailureListener(e->Toast.makeText(TranslateService.this,"Download translation model first",Toast.LENGTH_SHORT).show());}}).addOnCompleteListener(task->{bmp.recycle();busy=false;});}public void onFailure(int error){controls.setVisibility(View.VISIBLE);busy=false;Toast.makeText(TranslateService.this,"Screen capture unavailable: "+error,Toast.LENGTH_SHORT).show();}}),250);}
 void show(Rect r,String value){TextView t=new TextView(this);t.setText(value);t.setTextColor(Color.WHITE);t.setBackgroundColor(0xff202820);t.setTextSize(12);t.setGravity(Gravity.CENTER);WindowManager.LayoutParams p=params(Math.max(r.width(),70),Math.max(r.height(),32),true);p.gravity=Gravity.TOP|Gravity.LEFT;p.x=r.left;p.y=r.top;wm.addView(t,p);labels.add(t);}
 public void onAccessibilityEvent(AccessibilityEvent e){if(e.getEventType()==AccessibilityEvent.TYPE_VIEW_SCROLLED||e.getEventType()==AccessibilityEvent.TYPE_WINDOW_STATE_CHANGED){generation++;if(wm!=null)clearLabels();}}
 public void onInterrupt(){} public void onDestroy(){generation++;handler.removeCallbacksAndMessages(null);if(wm!=null){clearLabels();if(controls!=null)wm.removeView(controls);}if(translator!=null)translator.close();if(recognizer!=null)recognizer.close();super.onDestroy();}
}
